css:
@import url("https://fonts.googleapis.com/css2?family=Russo+One&family=Ubuntu:wght@400;500;700&display=swap");
:root{--wb:#0077B6;--wb2:#005A8C;--or:#FF6B00;--pb:#E7F4FB;--ink:#10212E;--gr:#51606B;--ln:#D3E4EE;--h:"Russo One",Impact,sans-serif;--b:"Ubuntu",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.6;color:var(--ink);background:#fff;padding-bottom:64px}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:400;margin:0;line-height:1.05}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--or);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--or);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:76px;position:relative}.logo{font-family:var(--h);font-size:24px;text-decoration:none;color:var(--wb);display:flex;gap:8px;align-items:center}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:var(--wb)}
.burger{display:none;background:none;border:2px solid var(--wb);color:var(--wb);width:44px;height:40px;border-radius:8px;font-size:20px;cursor:pointer}
.emg{position:fixed;left:0;right:0;bottom:0;z-index:50;background:var(--or);color:#fff}.emg .wrap{display:flex;justify-content:space-between;align-items:center;gap:10px;min-height:64px;flex-wrap:wrap}.emg b{font-size:17px}.emg a{background:#fff;color:var(--or);font-weight:700;text-decoration:none;padding:10px 18px;border-radius:30px}
.hero{background:var(--wb);color:#fff;position:relative;overflow:hidden}.hg{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:center;padding:50px 0 70px}.hg>*{min-width:0}
.hero h1{font-size:clamp(42px,5.6vw,74px)}.hero p{font-size:20px;color:#CDE8F7;margin:18px 0 22px;max-width:28em}
.badges{display:flex;flex-wrap:wrap;gap:10px}.badges span{background:rgba(255,255,255,.14);border-radius:30px;padding:6px 14px;font-size:15px}
.hero img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:24px 24px 120px 24px}
.btn{display:inline-block;background:var(--or);color:#fff;text-decoration:none;font:700 17px var(--b);padding:14px 24px;border-radius:40px;border:0;cursor:pointer}.btn.w{background:#fff;color:var(--wb)}
.row{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}
section{padding:80px 0}.sh{max-width:640px;margin-bottom:28px}.sh h2{font-size:clamp(32px,4.4vw,52px);color:var(--wb2)}.sh p{color:var(--gr);margin:10px 0 0}
.qg{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:start}.qg>*{min-width:0}
.jobs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:18px}.jobs label{position:relative;cursor:pointer}.jobs input{position:absolute;opacity:0;width:1px;height:1px;left:0;top:0}.jobs span{display:block;border:2px solid var(--ln);border-radius:16px;padding:14px;text-align:center;font-weight:500;height:100%}.jobs span i{display:block;font-style:normal;font-size:26px}
.jobs input:checked+span{border-color:var(--wb);background:var(--pb)}.jobs input:focus-visible+span{outline:3px solid var(--or)}
.qf .lb,.qf label.l{display:block;font-weight:700;font-size:15px;margin:0 0 8px}.seg{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.seg button{font:500 15px var(--b);border:2px solid var(--ln);background:#fff;border-radius:30px;padding:8px 14px;cursor:pointer;color:var(--ink)}.seg button[aria-pressed=true]{background:var(--ink);color:#fff;border-color:var(--ink)}
.qf .ck{display:flex;gap:10px;align-items:center;margin:6px 0;font-size:16px}.qf .ck input{width:20px;height:20px;accent-color:var(--wb)}
.qr{background:var(--ink);color:#fff;border-radius:22px;padding:26px;position:sticky;top:16px}.qr small{color:#A9BBC8}.qr .big{font-family:var(--h);font-size:46px;color:var(--or);margin:6px 0}.qr ul{padding-left:18px;color:#CFDCE5;font-size:15px;margin:10px 0 18px}
.area{background:var(--pb)}.ac{display:flex;gap:10px;flex-wrap:wrap;max-width:520px}.ac input{flex:1 1 200px;font:17px var(--b);padding:13px 16px;border:2px solid var(--ln);border-radius:40px;text-transform:uppercase}.ac label{position:absolute;left:-999px}
.ar{margin-top:14px;font-weight:700;min-height:28px}.ar.y{color:#15803D}.ar.n{color:#B45309}
.towns{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.towns span{background:#fff;border-radius:30px;padding:5px 12px;font-size:15px}
.svc{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.svc div{border:2px solid var(--ln);border-radius:18px;padding:20px}.svc img{border-radius:12px;aspect-ratio:3/2;object-fit:cover;width:100%;margin-bottom:12px}.svc h3{font-size:20px;color:var(--wb2)}.svc p{margin:6px 0 0;color:var(--gr);font-size:15px}
footer{padding:26px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hg,.qg{grid-template-columns:1fr}.hero img{max-width:380px;aspect-ratio:1}.svc{grid-template-columns:1fr 1fr}.qr{position:static}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:76px;left:0;right:0;background:#fff;flex-direction:column;padding:18px 22px;z-index:30;box-shadow:0 10px 20px rgba(0,0,0,.06)}.menu.open{display:flex}.jobs{grid-template-columns:1fr 1fr}.svc{grid-template-columns:1fr}.emg b{font-size:15px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);let u=1;
function q(){const j=document.querySelector('input[name=j]:checked'),base=+j.value*u+($('wk').checked?40:0),parts=$('pk').checked?Math.round(j.value*.35):0;const lo=Math.round(base+parts),hi=Math.round((base+parts)*1.25/5)*5;
$('qp').textContent=`£${lo} to £${hi}`;$('qd').textContent=`${j.dataset.n}, about ${j.dataset.h} hour${j.dataset.h==='1'?'':'s'} of work`;
$('ql').innerHTML=`<li>${u>1.5?'Emergency call-out, 90 minute arrival':u>1?'Same-day visit':'Visit this week at a time you choose'}</li>${$('wk').checked?'<li>Evening or weekend charge included</li>':''}<li>${parts?'Typical parts included':'Parts extra, charged at cost'}</li><li>12 month guarantee on our work</li>`}
$('qf').addEventListener('change',q);$('urg').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('urg').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));u=+b.dataset.u;q()};q();
const OK=['BS1','BS2','BS3','BS4','BS5','BS6','BS7','BS8','BS9','BS10','BS13','BS14','BS15','BS16','BS20','BS21','BS31','BS35','BA1','BA2'];
$('af').onsubmit=e=>{e.preventDefault();const p=$('pc').value.trim().toUpperCase().replace(/\s.*$/,'');const r=$('ar');if(!p){r.textContent='Please type a postcode.';r.className='ar n';return}
if(OK.includes(p)){r.textContent=`Yes, we cover ${p}. Usual arrival for emergencies: under 90 minutes.`;r.className='ar y'}else{r.textContent=`${p} is outside our usual area. Call us anyway and we'll try to help or recommend someone.`;r.className='ar n'}};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
